#!/bin/bash
#SBATCH --job-name=C-wssr6-E500x3
#SBATCH --account=def-ortner
#SBATCH --time=01:30:00
#SBATCH --cpus-per-task=8
#SBATCH --mem=100G
#SBATCH --gpus-per-node=h100:1
#SBATCH --exclude=fc10405,fc10420,fc10512
#SBATCH --array=0-11%4
#SBATCH --output=/scratch/dexuan1/runs/logs/%x-%A_%a.out
#SBATCH --error=/scratch/dexuan1/runs/logs/%x-%A_%a.err
set -euo pipefail
ROOT=/scratch/dexuan1/vmcnet/experiments/C_wssr_six_improvements;SEL=$ROOT/results/stage1/selection.json;TOP=$ROOT/results/stage2/top3.json;SOURCE=/scratch/dexuan1/runs/pilot/C/C_kfac_pre1000_1;MI=$((SLURM_ARRAY_TASK_ID/3));SEED=$((SLURM_ARRAY_TASK_ID%3))
if ((MI==0));then M=baseline;P=warm2;else read M P < <(python -c "import json;x=json.load(open('$TOP'))[$((MI-1))];print(x['method'],x['parameter'])");fi
MODE=$M;TARGET=400;RANK=400;COMP=0;GAP=.002;TAIL=0;BETA=0;SS=-1;SE=-1;FORCE=0;CG=0
case $M in baseline)MODE=none;;cluster)RANK=512;GAP=$P;;near_tail)TAIL=$P;RANK=$((400+P));;adaptive_complement)BETA=$P;COMP=.0001;;smooth)SS=${P%-*};SE=${P#*-};RANK=$SE;;force_aware)[[ $P == force+krylov ]]&&FORCE=2||FORCE=1;;iterative_complement)CG=$P;;esac
V=${M}_${P//+/_};RUN=/scratch/dexuan1/runs/C_wssr6_stage3_E500/$V/seed$SEED;META=${RUN}.metadata;[[ -f $SOURCE/checkpoints/1000.npz && ! -e $RUN && ! -e $META ]]||exit 2;mkdir -p "$META" /scratch/dexuan1/runs/logs
module --force purge;module load StdEnv/2023 gcc/12.3 python/3.11.5;source /home/dexuan1/projects/rrg-ortner/dexuan1/venvs/vmcnet311/bin/activate;export WANDB_MODE=disabled WANDB_DISABLED=true XLA_PYTHON_CLIENT_PREALLOCATE=false WSSR_STAGE3_SEED=$SEED SMOKE_TIMING_DIR=$META;cd /scratch/dexuan1/vmcnet;hostname > "$META/hostname.txt";nvidia-smi > "$META/nvidia_smi.txt";git rev-parse HEAD > "$META/git_hash.txt";git status --short > "$META/git_status.txt";echo 'timestamp_unix,memory_used_mib' > "$META/gpu_memory_poll.csv";(while true;do T=$(date +%s.%N);nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits|awk -v t="$T" '{print t "," $1}' >> "$META/gpu_memory_poll.csv"||true;sleep 1;done)&MON=$!;cleanup(){ kill $MON 2>/dev/null||true;wait $MON 2>/dev/null||true;};trap cleanup EXIT INT TERM
python experiments/C_wssr_six_improvements/seeded_training_launcher.py --reload.logdir=$SOURCE --reload.checkpoint_relative_file_path=checkpoints/1000.npz --reload.use_config_file=True --reload.use_checkpoint_file=True --reload.new_optimizer_state=True --reload.reburn=True --reload.append=False --reload.same_logdir=False --config.logdir=$RUN --config.save_to_current_datetime_subfolder=False --config.subfolder_name=NONE --config.problem.nelec='(4,2)' --config.vmc.nchains=1000 --config.vmc.nburn=5000 --config.vmc.nepochs=500 --config.vmc.nsteps_per_param_update=10 --config.vmc.clip_center=mean --config.vmc.clip_threshold=5 --config.vmc.check_for_nans=True --config.vmc.checkpoint_every=500 --config.vmc.best_checkpoint_every=500 --config.eval.nepochs=0 --config.wandb.mode=disabled --config.vmc.optimizer_type=wssr_warm_svd_right --config.vmc.optimizer.wssr_warm_svd_right.schedule_type=inverse_time --config.vmc.optimizer.wssr_warm_svd_right.learning_rate=.02 --config.vmc.optimizer.wssr_warm_svd_right.learning_decay_rate=.0001 --config.vmc.optimizer.wssr_warm_svd_right.eta=.8 --config.vmc.optimizer.wssr_warm_svd_right.damping=.0003 --config.vmc.optimizer.wssr_warm_svd_right.spectral_regularization=tikhonov --config.vmc.optimizer.wssr_warm_svd_right.complement_weight=$COMP --config.vmc.optimizer.wssr_warm_svd_right.constrain_norm=True --config.vmc.optimizer.wssr_warm_svd_right.norm_constraint=.001 --config.vmc.optimizer.wssr_warm_svd_right.sr_rank=$RANK --config.vmc.optimizer.wssr_warm_svd_right.sr_rank_max=$RANK --config.vmc.optimizer.wssr_warm_svd_right.sr_storage_rank=$RANK --config.vmc.optimizer.wssr_warm_svd_right.svd_working_rank=$RANK --config.vmc.optimizer.wssr_warm_svd_right.store_warm_u=True --config.vmc.optimizer.wssr_warm_svd_right.svd_maxiter_initial=8 --config.vmc.optimizer.wssr_warm_svd_right.svd_maxiter_warm=2 --config.vmc.optimizer.wssr_warm_svd_right.exact_first=False --config.vmc.optimizer.wssr_warm_svd_right.update_diagnostics=True --config.vmc.optimizer.wssr_warm_svd_right.experimental_mode=$MODE --config.vmc.optimizer.wssr_warm_svd_right.experimental_target_rank=$TARGET --config.vmc.optimizer.wssr_warm_svd_right.cluster_gap_threshold=$GAP --config.vmc.optimizer.wssr_warm_svd_right.near_tail_modes=$TAIL --config.vmc.optimizer.wssr_warm_svd_right.adaptive_complement_beta=$BETA --config.vmc.optimizer.wssr_warm_svd_right.smooth_transition_start=$SS --config.vmc.optimizer.wssr_warm_svd_right.smooth_transition_end=$SE --config.vmc.optimizer.wssr_warm_svd_right.force_aware_krylov_vectors=$FORCE --config.vmc.optimizer.wssr_warm_svd_right.iterative_complement_iterations=$CG
